<script>
    (function() {
        // --- UTILITY & LOGIC FUNCTIONS ---
        function SafeGetValue(obj, path, defaultValue = 0) {
            const keys = path.split('.'); let current = obj;
            for (const key of keys) {
                if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(key)) return defaultValue;
                current = current[key];
            }
            if (Array.isArray(current) && current.length > 0) return current[0];
            return current ?? defaultValue;
        }

        function getCharacterStage(characterKey, h, d) {
            switch (characterKey) {
                case '空野 镜':
                    if (h >= 95 && d >= 95) return "共犯的女王"; if (h >= 95 && d <= 5) return "思想的伴侣";
                    if (h <= -95 && d >= 95) return "憎恨的契约"; if (Math.abs(h) < 10 && d >= 95) return "冰冷的程序";
                    if (h > 50 && d > 50) return "屈服的支配者"; if (h > 50 && d > 5 && d <= 50) return "危险的博弈者";
                    if (h > 50 && d <= 5) return "警惕的盟友"; if (h > -30 && h <= 50 && d > 50) return "矛盾的共犯";
                    if (h < -30 && d > 50) return "屈辱的战利品"; if (h <= 50 && d <= 50) return "计划的干涉者";
                    return "状态未定义";
                case '空野 凪':
                    if (h >= 95 && d >= 95) return "献身的宠物"; if (h >= 95 && d <= 5) return "唯一的对手";
                    if (h <= -95 && d >= 95) return "笼中的困兽"; if (Math.abs(h) < 10 && d >= 95) return "刺激的游戏";
                    if (h > 50 && d > 50) return "不情愿的宠物"; if (h > 50 && d > 5 && d <= 50) return "危险的游戏伙伴";
                    if (h > 50 && d <= 5) return "认同的强者"; if (h > -30 && h <= 50 && d > 50) return "好奇的实验者";
                    if (h < -30 && d > 50) return "憎恨的玩物"; if (h <= -30 && d <= 50) return "领地的入侵者";
                    return "状态未定义";
                case '夏风 铃':
                    if (h >= 95 && d >= 95) return "献身的太阳"; if (h >= 95 && d <= 5) return "神圣的信徒";
                    if (h <= -95 && d >= 95) return "破碎的向日葵"; if (Math.abs(h) < 10 && d >= 95) return "习惯性慰藉";
                    if (h > 50 && d > 50) return "甜蜜的负罪感"; if (h > 50 && d > 5 && d <= 50) return "动摇的圣女";
                    if (h > 50 && d <= 5) return "被救赎的少女"; if (h > -30 && h <= 50 && d > 50) return "迷茫的羔羊";
                    if (h < -30 && d > 50) return "矛盾的渴求"; if (h <= 50 && d <= 50) return "信念的守护者";
                    return "状态未定义";
                case '空野 茧':
                    if (h >= 95 && d >= 95) return "新家的主妇"; if (h >= 95 && d <= 5) return "理想的儿子";
                    if (h <= -95 && d >= 95) return "空洞的圣母"; if (Math.abs(h) < 10 && d >= 95) return "温暖的毒药";
                    if (h > 50 && d > 50) return "错位的爱人"; if (h > 50 && d > 5 && d <= 50) return "危险的动摇";
                    if (h > 50 && d <= 5) return "可靠的男人"; if (h > -30 && h <= 50 && d > 50) return "背德的慰藉";
                    if (h < -30 && d > 50) return "危险的梦游"; if (h <= 50 && d <= 50) return "爱子的警卫";
                    return "状态未定义";
                default: return "未知角色";
            }
        }

        function getCharacterEvents(characterKey) {
            const events = {
                '空野 镜': [
                    { title: "共犯的提案", condition: "好感度≥95 & 堕落度≥95", check: (h, d) => h >= 95 && d >= 95 },
                    { title: "憎恨的契约", condition: "好感度≤-95 & 堕落度≥95", check: (h, d) => h <= -95 && d >= 95 },
                    { title: "冰冷的献身", condition: "好感度≈0 & 堕落度≥95", check: (h, d) => Math.abs(h) < 10 && d >= 95 },
                    { title: "唯一的合伙人", condition: "好感度≥95 & 堕落度≤5", check: (h, d) => h >= 95 && d <= 5 },
                    { title: "憎恨的办公室", condition: "好感度<-40 & 60<堕落度<95", check: (h, d) => h < -40 && d > 60 && d < 95 },
                    { title: "办公室的屈服", condition: "好感度>60 & 20<堕落度<95", check: (h, d) => h > 60 && d > 20 && d < 95 },
                    // [Kora v1.1 修正] - 此处文本已根据 '自动化核心 v1.6' 的真理源进行手动同步修正
                    { title: "公开的挑战", condition: "好感度≤-80 & 堕落度<95", check: (h, d) => h <= -80 && d < 95 },
                    { title: "意外的败北", condition: "好感度>40 & 10<堕落度≤30", check: (h, d) => h > 40 && d > 10 && d <= 30 },
                    { title: "失控的拥抱", condition: "好感度>30 & 堕落度≤20", check: (h, d) => h > 30 && d <= 20 },
                    { title: "理性的裂痕", condition: "好感度>0 & 堕落度=0", check: (h, d) => h > 0 && d === 0 },
                    { title: "计划的干涉", condition: "好感度<-30 & 堕落度≤5", check: (h, d) => h < -30 && d <= 5 }
                ],
                '空野 凪': [
                    { title: "主人的命令", condition: "好感度≥95 & 堕落度≥95", check: (h, d) => h >= 95 && d >= 95 }, { title: "笼中的困兽", condition: "好感度≤-95 & 堕落度≥95", check: (h, d) => h <= -95 && d >= 95 }, { title: "无聊的游戏", condition: "好感度≈0 & 堕落度≥95", check: (h, d) => Math.abs(h) < 10 && d >= 95 }, { title: "唯一的对手", condition: "好感度≥95 & 堕落度≤5", check: (h, d) => h >= 95 && d <= 5 }, { title: "反抗的游戏", condition: "好感度<-60 & 70<堕落度<95", check: (h, d) => h < -60 && d > 70 && d < 95 }, { title: "挣扎的宠物", condition: "好感度>60 & 50<堕落度<95", check: (h, d) => h > 60 && d > 50 && d < 95 }, { title: "哥哥的守护者", condition: "好感度≤-80 & 堕落度<95", check: (h, d) => h <= -80 && d < 95 }, { title: "项圈的归属", condition: "好感度>50 & 30<堕落度≤50", check: (h, d) => h > 50 && d > 30 && d <= 50 }, { title: "反向的恶作剧", condition: "好感度>20 & 堕落度≤30", check: (h, d) => h > 20 && d <= 30 }, { title: "游戏中的绝对支配", condition: "好感度>-10 & 堕落度=0", check: (h, d) => h > -10 && d === 0 }, { title: "所有物的侵犯", condition: "好感度<-40 & 堕落度≤5", check: (h, d) => h < -40 && d <= 5 }
                ],
                '夏风 铃': [
                    { title: "阳光下的誓言", condition: "好感度≥95 & 堕落度≥95", check: (h, d) => h >= 95 && d >= 95 }, { title: "破碎的向日葵", condition: "好感度≤-95 & 堕落度≥95", check: (h, d) => h <= -95 && d >= 95 }, { title: "习惯性的拥抱", condition: "好感度≈0 & 堕落度≥95", check: (h, d) => Math.abs(h) < 10 && d >= 95 }, { title: "神圣的守护者", condition: "好感度≥95 & 堕落度≤5", check: (h, d) => h >= 95 && d <= 5 }, { title: "医务室的告白", condition: "好感度>70 & 10<堕落度<95", check: (h, d) => h > 70 && d > 10 && d < 95 }, { title: "泪水的慰藉", condition: "好感度<-20 & 50<堕落度<95", check: (h, d) => h < -20 && d > 50 && d < 95 }, { title: "友情的背叛", condition: "好感度≤-50 & 堕落度<95", check: (h, d) => h <= -50 && d < 95 }, { title: "动摇的信仰", condition: "好感度>70 & 堕落度≤10", check: (h, d) => h > 70 && d <= 10 }, { title: "雨中的肩膀", condition: "好感度>40 & 堕落度≤10", check: (h, d) => h > 40 && d <= 10 }, { title: "被看见的辛劳", condition: "好感度>15 & 堕落度=0", check: (h, d) => h > 15 && d === 0 }, { title: "善良的践踏", condition: "好感度<-20 & 堕落度≤5", check: (h, d) => h < -20 && d <= 5 }
                ],
                '空野 茧': [
                    { title: "爱巢的共筑", condition: "好感度≥95 & 堕落度≥95", check: (h, d) => h >= 95 && d >= 95 }, { title: "空洞的圣母", condition: "好感度≤-95 & 堕落度≥95", check: (h, d) => h <= -95 && d >= 95 }, { title: "没有温度的拥抱", condition: "好感度≈0 & 堕落度≥95", check: (h, d) => Math.abs(h) < 10 && d >= 95 }, { title: "理想的儿子", condition: "好感度≥95 & 堕落度≤5", check: (h, d) => h >= 95 && d <= 5 }, { title: "禁断的继母", condition: "好感度<-30 & 80<堕落度<95", check: (h, d) => h < -30 && d > 80 && d < 95 }, { title: "错位的母爱", condition: "好感度>80 & 70<堕落度<95", check: (h, d) => h > 80 && d > 70 && d < 95 }, { title: "母亲的敌人", condition: "好感度≤-60 & 堕落度<95", check: (h, d) => h <= -60 && d < 95 }, { title: "填满空虚的夜晚", condition: "好感度>60 & 25<堕落度≤70", check: (h, d) => h > 60 && d > 25 && d <= 70 }, { title: "厨房里的依靠", condition: "好感度>35 & 堕落度≤25", check: (h, d) => h > 35 && d <= 25 }, { title: "被看见的女人", condition: "好感度>10 & 堕落度=0", check: (h, d) => h > 10 && d === 0 }, { title: "独立的宣言", condition: "好感度<-20 & 堕落度≤5", check: (h, d) => h < -20 && d <= 5 }
                ]
            };
            return events[characterKey] || [];
        }

        function updateProgressBar(barId, valueId, value, min, max, colorVar) {
            const bar = document.getElementById(barId); const text = document.getElementById(valueId); if (!bar || !text) return;
            const numericValue = parseFloat(value); if (isNaN(numericValue)) { text.innerText = String(value); bar.style.width = '0%'; return; }
            text.innerText = String(numericValue); const range = max - min; const percentage = range === 0 ? 100 : ((numericValue - min) / range) * 100;
            bar.style.width = `${Math.max(0, Math.min(100, percentage))}%`; bar.style.backgroundColor = `var(${colorVar})`;
        }
        function toggleSection(headerElement) {
            const contentElement = headerElement.nextElementSibling; if (!contentElement) return;
            const isExpanded = contentElement.style.display === 'block'; contentElement.style.display = isExpanded ? 'none' : 'block'; headerElement.classList.toggle('expanded', !isExpanded);
        }
        function switchTab(tabElement) {
            if (!tabElement || tabElement.classList.contains('active')) return; const targetId = tabElement.dataset.target; const contentContainer = tabElement.closest('.section-content'); if (!contentContainer) return;
            contentContainer.querySelectorAll('.nav-tab').forEach(t => t.classList.remove('active')); contentContainer.querySelectorAll('.tab-pane').forEach(p => p.classList.remove('active'));
            tabElement.classList.add('active'); const targetPane = document.getElementById(targetId); if (targetPane) targetPane.classList.add('active');
        }
        function setTheme(themeClass) {
            const body = document.body; if (!body) return; body.className = ''; body.classList.add(themeClass);
            document.querySelectorAll('.theme-button').forEach(btn => { btn.classList.toggle('active', btn.dataset.theme === themeClass); });
        }

        async function updateDisplay() {
            try {
                let currentData, previousData;
                if (typeof getChatMessages === 'function' && typeof getCurrentMessageId === 'function') {
                    const messages = await getChatMessages(getCurrentMessageId());
                    if (messages && messages.length > 0 && messages[0].data && messages[0].data.stat_data) {
                        currentData = messages[0].data.stat_data;
                        for (let i = 1; i < messages.length; i++) {
                            if (messages[i].data && messages[i].data.stat_data) {
                                previousData = messages[i].data.stat_data; break;
                            }
                        }
                    }
                }
                if (!currentData) {
                    currentData = { "世界": { "时间": ["午休"], "地点": ["学园"] }, "空野 镜": { "好感度": [-20], "堕落度": [0] }, "空野 凪": { "好感度": [-30], "堕落度": [0] }, "夏风 铃": { "好感度": [15], "堕落度": [0] }, "空野 茧": { "好感度": [10], "堕落度": [0] } };
                    previousData = currentData;
                }
                if (!previousData) previousData = currentData;

                document.getElementById('world-time').innerText = SafeGetValue(currentData, '世界.时间', '未知');
                document.getElementById('world-location').innerText = SafeGetValue(currentData, '世界.地点', '未知');
                const characters = [ { key: '空野 镜', prefix: 'kyou' }, { key: '空野 凪', prefix: 'nagi' }, { key: '夏风 铃', prefix: 'rin' }, { key: '空野 茧', prefix: 'mayu' } ];

                characters.forEach(char => {
                    const h_curr = parseFloat(SafeGetValue(currentData, `${char.key}.好感度`));
                    const d_curr = parseFloat(SafeGetValue(currentData, `${char.key}.堕落度`));
                    const h_prev = parseFloat(SafeGetValue(previousData, `${char.key}.好感度`));
                    const d_prev = parseFloat(SafeGetValue(previousData, `${char.key}.堕落度`));

                    document.getElementById(`${char.prefix}-stage`).innerText = getCharacterStage(char.key, h_curr, d_curr);
                    updateProgressBar(`${char.prefix}-affection-bar`, `${char.prefix}-affection`, h_curr, -100, 100, '--affection-color');
                    updateProgressBar(`${char.prefix}-corruption-bar`, `${char.prefix}-corruption`, d_curr, 0, 100, '--corruption-color');

                    const eventsList = document.getElementById(`${char.prefix}-events-list`);
                    if (eventsList) {
                        eventsList.innerHTML = '';
                        const allEvents = getCharacterEvents(char.key);
                        let hasPendingEvents = false;
                        const triggeredEvents = [];
                        const pendingEvents = [];

                        allEvents.forEach(event => {
                            const isCurrentlyTriggered = event.check(h_curr, d_curr);
                            const wasPreviouslyTriggered = event.check(h_prev, d_prev);

                            const li = document.createElement('li');
                            li.className = 'event-item';
                            li.innerHTML = `<div class="event-title">${event.title}</div><div class="event-condition">${event.condition}</div>`;

                            if (isCurrentlyTriggered && !wasPreviouslyTriggered) {
                                li.classList.add('just-triggered');
                                triggeredEvents.unshift(li); // Show just-triggered events at the top
                            } else if (isCurrentlyTriggered) {
                                li.classList.add('triggered');
                                triggeredEvents.push(li);
                            } else {
                                li.classList.add('pending');
                                pendingEvents.push(li);
                                hasPendingEvents = true;
                            }
                        });

                        // Render sorted lists
                        triggeredEvents.forEach(li => eventsList.appendChild(li));
                        pendingEvents.forEach(li => eventsList.appendChild(li));

                        if (!hasPendingEvents && allEvents.length > 0 && eventsList.children.length === allEvents.length) {
                             const li = document.createElement('li');
                             li.className = 'event-item triggered';
                             li.innerHTML = `<div class="event-title" style="text-align:center; color: var(--text-success);">已触发所有特殊事件</div>`;
                             eventsList.appendChild(li);
                        }
                    }
                });
            } catch (error) { console.error("Status bar failed to update:", error); }
        }

        function init() {
            document.querySelectorAll('.section-header, .events-header').forEach(h => h.addEventListener('click', () => toggleSection(h)));
            document.querySelectorAll('.nav-tab').forEach(tab => tab.addEventListener('click', () => switchTab(tab)));
            document.querySelectorAll('.theme-button').forEach(button => button.addEventListener('click', () => setTheme(button.dataset.theme)));
            const savedTheme = 'theme-night';
            setTheme(savedTheme);
            const firstTab = document.querySelector('.nav-tab'); if (firstTab) switchTab(firstTab);
            updateDisplay();
        }
        if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); } else { init(); }
    })();
</script>
</body>
</html>
